{
  "merchantOrderId": "{{merchant_order_id}}", // auto-generated each run (ORDER_<timestamp>)
  "amount": {{setup_amount}}, // MAX debit/redemption amount in paise (PENNY_DROP must be 200; TRANSACTION >= 100)
  "expireAt": {{subscription_expire_at}}, // order expiry in epoch ms (auto-defaulted to now+10min)
  "paymentFlow": {
    "type": "SUBSCRIPTION_SETUP",
    "merchantSubscriptionId": "{{merchant_subscription_id}}", // auto-generated each run (SUB_<timestamp>)
    "authWorkflowType": "{{auth_workflow_type}}", // PENNY_DROP or TRANSACTION
    "amountType": "FIXED", // FIXED or VARIABLE
    "maxAmount": {{max_amount}}, // max amount up to which redemptions are allowed (paise)
    "frequency": "{{frequency}}", // DAILY / WEEKLY / MONTHLY / YEARLY / FORTNIGHTLY / BIMONTHLY / QUARTERLY / HALFYEARLY / ON_DEMAND
    "paymentMode": {
      "type": "UPI_INTENT",
      "targetApp": "{{target_app}}" // Android: UPI app package name; iOS: PHONEPE / GPAY / PAYTM
    }
  },
  "constraints": [
    {
      "type": "ACCOUNT",
      "accountNumber": "{{account_number}}", // enter the allowed bank account number here (TPV restriction)
      "ifsc": "{{ifsc}}" // enter the allowed bank IFSC here
    }
  ],
  "deviceContext": {
    "deviceOS": "{{device_os}}" // ANDROID or iOS
  }
}

